import React, { useState, useEffect, useCallback } from 'react';
import { useApp } from '../context/AppContext';
import { adminApi } from '../api/adminApi';
import { withTokenExpiry } from '../api/authApi';
import { useAuth } from '../context/AuthContext';
import { Card, Badge, SectionHeader, Empty, ErrorCard, SkeletonCard } from '../components/ui/UI';
import { RelocationCalendarResultView } from './RelocationCalendarPage';
import s from './AdminPage.module.css';

export function AdminPage() {
  const { toast } = useApp();
  const { goScreen, logout } = useAuth();
  const authCtx = { goScreen, logout };

  const [users, setUsers] = useState(null);
  const [usersError, setUsersError] = useState(null);
  const [selectedUser, setSelectedUser] = useState(null);

  const [calendars, setCalendars] = useState(null);
  const [calendarsLoading, setCalendarsLoading] = useState(false);
  const [calendarsError, setCalendarsError] = useState(null);

  const [selectedCalendar, setSelectedCalendar] = useState(null); // full detail, incl. result
  const [detailLoading, setDetailLoading] = useState(false);

  const [view, setView] = useState('formatted'); // formatted | edit
  const [jsonText, setJsonText] = useState('');
  const [jsonError, setJsonError] = useState(null);
  const [saving, setSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);

  const loadUsers = useCallback(() => {
    setUsersError(null);
    withTokenExpiry(adminApi.listUsers(), authCtx)
      .then(d => setUsers(d.users))
      .catch(e => { if (e?.code !== 'TokenExpired') setUsersError(e.message || 'Could not load users.'); });
    // eslint-disable-next-line
  }, []);

  useEffect(() => { loadUsers(); }, [loadUsers]);

  const selectUser = (user) => {
    setSelectedUser(user);
    setSelectedCalendar(null);
    setCalendars(null);
    setCalendarsLoading(true);
    setCalendarsError(null);
    withTokenExpiry(adminApi.listUserCalendars(user.user_id), authCtx)
      .then(d => setCalendars(d.items))
      .catch(e => { if (e?.code !== 'TokenExpired') setCalendarsError(e.message || "Could not load this user's calendars."); })
      .finally(() => setCalendarsLoading(false));
  };

  const selectCalendar = (cal) => {
    setDetailLoading(true);
    setSaveSuccess(false);
    withTokenExpiry(adminApi.getUserCalendar(selectedUser.user_id, cal.analysis_id), authCtx)
      .then(d => {
        setSelectedCalendar(d);
        setJsonText(JSON.stringify(d.result, null, 2));
        setJsonError(null);
        setView('formatted');
      })
      .catch(e => { if (e?.code !== 'TokenExpired') toast({ type: 'error', message: e.message || 'Could not load calendar detail.' }); })
      .finally(() => setDetailLoading(false));
  };

  const handleJsonChange = (text) => {
    setJsonText(text);
    try {
      JSON.parse(text);
      setJsonError(null);
    } catch {
      setJsonError('Invalid JSON — fix the syntax before saving.');
    }
  };

  const save = async () => {
    let parsed;
    try {
      parsed = JSON.parse(jsonText);
    } catch {
      setJsonError('Invalid JSON — fix the syntax before saving.');
      return;
    }
    setSaving(true);
    setSaveSuccess(false);
    try {
      const updated = await withTokenExpiry(
        adminApi.updateUserCalendar(selectedUser.user_id, selectedCalendar.analysis_id, parsed),
        authCtx
      );
      setSelectedCalendar(updated);
      setJsonText(JSON.stringify(updated.result, null, 2));
      setSaveSuccess(true);
      toast({ type: 'success', message: "✓ Saved — this user's calendar has been updated." });
    } catch (e) {
      if (e?.code !== 'TokenExpired') toast({ type: 'error', message: e.message || 'Could not save changes.' });
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className={s.page}>
      <SectionHeader title="Admin" subtitle="View and manage every user's account, and edit their scheduled social media calendars." />

      <div className={s.layout}>
        <Card>
          <SectionHeader title="Users" />
          {!users && !usersError && <SkeletonCard rows={5} />}
          {usersError && <ErrorCard message={usersError} />}
          {users && users.length === 0 && <Empty icon="👤" title="No users yet" body="Registered users will show up here." />}
          {users && users.length > 0 && (
            <div className={s.userList}>
              {users.map(u => (
                <button
                  key={u.user_id}
                  type="button"
                  className={`${s.userRow} ${selectedUser?.user_id === u.user_id ? s.userRowActive : ''}`}
                  onClick={() => selectUser(u)}
                >
                  <span className={s.userName}>{u.full_name || u.email}</span>
                  <span className={s.userEmail}>{u.email} · {u.company_name}</span>
                  <div className={s.userMeta}>
                    {u.is_admin && <Badge variant="brand">Admin</Badge>}
                    <Badge variant={u.is_paid ? 'success' : 'warning'}>{u.is_paid ? 'Paid' : 'Free'}</Badge>
                  </div>
                </button>
              ))}
            </div>
          )}
        </Card>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {!selectedUser && (
            <Card><Empty icon="🗂️" title="Select a user" body="Pick a user on the left to see their scheduled social media calendars." /></Card>
          )}

          {selectedUser && (
            <Card>
              <SectionHeader title={`${selectedUser.full_name || selectedUser.email}'s calendars`} />
              {calendarsLoading && <SkeletonCard rows={3} />}
              {calendarsError && <ErrorCard message={calendarsError} />}
              {calendars && calendars.length === 0 && (
                <Empty icon="📅" title="No calendars yet" body="This user hasn't generated a social media calendar." />
              )}
              {calendars && calendars.length > 0 && (
                <div className={s.calendarList}>
                  {calendars.map(c => (
                    <button
                      key={c.analysis_id}
                      type="button"
                      className={`${s.calendarRow} ${selectedCalendar?.analysis_id === c.analysis_id ? s.calendarRowActive : ''}`}
                      onClick={() => selectCalendar(c)}
                    >
                      <span>{c.country}</span>
                      <span className={s.calendarMeta}>{c.created_at?.slice(0, 10)}</span>
                    </button>
                  ))}
                </div>
              )}
            </Card>
          )}

          {detailLoading && <Card><SkeletonCard rows={6} /></Card>}

          {selectedCalendar && !detailLoading && (
            <Card>
              <div className={s.editorToolbar}>
                <SectionHeader title="Calendar detail" />
                <div style={{ display: 'flex', gap: 8 }}>
                  <button
                    type="button"
                    className={`${s.toggleBtn} ${view === 'formatted' ? s.toggleBtnActive : ''}`}
                    onClick={() => setView('formatted')}
                  >
                    Formatted
                  </button>
                  <button
                    type="button"
                    className={`${s.toggleBtn} ${view === 'edit' ? s.toggleBtnActive : ''}`}
                    onClick={() => setView('edit')}
                  >
                    Edit JSON
                  </button>
                </div>
              </div>

              {view === 'formatted' && <RelocationCalendarResultView result={selectedCalendar.result} />}

              {view === 'edit' && (
                <div>
                  <textarea
                    className={`${s.jsonEditor} ${jsonError ? 'invalid' : ''}`}
                    value={jsonText}
                    onChange={e => handleJsonChange(e.target.value)}
                    spellCheck={false}
                  />
                  {jsonError && <div className={s.jsonError}>{jsonError}</div>}
                  {saveSuccess && !jsonError && <div className={s.saveSuccess}>✓ Saved.</div>}
                  <div style={{ marginTop: 10 }}>
                    <button type="button" className={s.saveBtn} onClick={save} disabled={saving || !!jsonError}>
                      {saving ? 'Saving…' : 'Save changes'}
                    </button>
                  </div>
                </div>
              )}
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}
